package org.sleepwell.app;
import android.util.JsonReader;import android.util.JsonToken;import org.json.*;import java.io.*;import java.math.BigDecimal;import java.nio.*;import java.nio.charset.*;import java.util.*;
/** Small strict UTF-8 boundary, rejecting duplicate keys, trailing input and unsupported depth. */
final class SettingsProfileJson {
 static String read(InputStream input,java.util.function.BooleanSupplier active)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] block=new byte[4096];int empty=0;for(;;){BackupIo.active(active);int count=input.read(block);if(count<0)break;if(count==0){if(++empty>16)throw new IOException("The document provider returned no data.");continue;}empty=0;if(count>SettingsProfile.LIMIT-bytes.size())throw new IOException("Settings profiles must fit within 64 KiB.");bytes.write(block,0,count);}try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes.toByteArray())).toString();}catch(CharacterCodingException invalid){throw new IOException("Choose a UTF-8 JSON settings profile.",invalid);}}
 static JSONObject object(String text)throws JSONException{try(JsonReader reader=new JsonReader(new StringReader(text))){reader.setLenient(false);Object value=value(reader,0);if(!(value instanceof JSONObject)||reader.peek()!=JsonToken.END_DOCUMENT)throw new IOException("Choose one JSON settings object with no trailing content.");return (JSONObject)value;}catch(IOException|ArithmeticException invalid){throw new JSONException("Invalid settings JSON: "+invalid.getMessage());}}
 private static Object value(JsonReader reader,int depth)throws IOException,JSONException{if(depth>12)throw new IOException("Settings JSON nesting is too deep.");return switch(reader.peek()){case BEGIN_OBJECT->{reader.beginObject();JSONObject object=new JSONObject();Set<String> seen=new HashSet<>();while(reader.hasNext()){String key=reader.nextName();if(key.length()>100||!seen.add(key))throw new IOException("Duplicate or unsupported JSON field.");object.put(key,value(reader,depth+1));if(object.length()>64)throw new IOException("Too many settings fields.");}reader.endObject();yield object;}case BEGIN_ARRAY->{reader.beginArray();JSONArray rows=new JSONArray();while(reader.hasNext()){if(rows.length()>=32)throw new IOException("Too many settings entries.");rows.put(value(reader,depth+1));}reader.endArray();yield rows;}case STRING->{String text=reader.nextString();if(text.length()>2048)throw new IOException("Settings text is too long.");yield text;}case BOOLEAN->reader.nextBoolean();case NUMBER->{String text=reader.nextString();if(text.length()>32)throw new IOException("Invalid settings number.");yield new BigDecimal(text).longValueExact();}case NULL->{reader.nextNull();yield JSONObject.NULL;}default->throw new IOException("Unsupported settings JSON value.");};}
 private SettingsProfileJson(){}
}
